import json,subprocess,sys,random
sys.path.insert(0,'dev')
import fuzz
rnd=random.Random(2)
for it in range(40):
    req={'cases':[fuzz.gen_case(rnd) for _ in range(rnd.randrange(1,4))]}
    raw=json.dumps(req).encode()
    p=subprocess.run([sys.executable,'-I','-B','project/solver.py'],input=raw,stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd='/workspace')
    got=json.loads(p.stdout.decode())
    if 'error' in got:
        print('INVALID at round',it)
        for c in req['cases']:
            print(json.dumps(c)[:1500])
        import request as R
        try:
            R.load(raw); print('validator says OK??')
        except Exception as e: print('validator:',e)
        break
EOF
